package org.joda.time;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import org.joda.time.DateTimeFieldType;
import org.joda.time.base.AbstractPartial;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractPartialFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormat;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Partial_with_TriageGen0Test {

    @Test(expected = IllegalArgumentException.class)
    public void testWith_NullFieldType_ThrowsException() {
        Partial partial = new Partial(ISOChronology.getInstance());
        partial.with(null, 1);
    }

    @Test
    public void testWith_ExistingField_NewValue() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOfStandard();
        Partial partial = new Partial(yearType, 2020);

        Partial updated = partial.with(yearType, 2021);

        assertNotSame(partial, updated);
        assertEquals(2021, updated.getValue(0));
        assertEquals(1, updated.size());
    }

    @Test
    public void testWith_ExistingField_SameValue_ReturnsThis() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOfStandard();
        Partial partial = new Partial(yearType, 2020);

        Partial updated = partial.with(yearType, 2020);

        assertSame(partial, updated);
    }

    @Test
    public void testWith_NewField_InsertionAtBeginning() {
        // Case where the new field has a larger duration/unit than existing ones
        // to trigger the 'compare > 0' break logic or insertion at index 0
        DateTimeFieldType yearType = DateTimeFieldType.yearOfStandard();
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYear();

        // Start with month
        Partial partial = new Partial(monthType, 5);

        // Add year (Year is larger than month, should be inserted at index 0)
        Partial updated = partial.with(yearType, 2020);

        assertEquals(2, updated.size());
        // Check order: Year should be first if the logic sorts largest-to-smallest
        assertEquals(yearType, updated.getFieldType(0));
        assertEquals(2020, updated.getValue(0));
        assertEquals(monthType, updated.getFieldType(1));
        assertEquals(5, updated.getValue(1));
    }

    @Test
    public void testWith_NewField_InsertionInMiddleOrEnd() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOfStandard();
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYear();
        DateTimeFieldType dayType = DateTimeFieldType.dayOfMonth();

        Partial partial = new Partial(yearType, 2020);
        partial.with(monthType, 1); // This is internal logic, we use the return

        // Create partial with Year and Day
        Partial partialWithYearAndDay = new Partial(new DateTimeFieldType[]{yearType, dayType}, new int[]{2020, 15});

        // Add Month (Month is between Year and Day in terms of scale)
        Partial updated = partialWithYearAndDay.with(monthType, 6);

        assertEquals(3, updated.size());
        // Verify order (assuming Year > Month > Day)
        assertEquals(yearType, updated.getFieldType(0));
        assertEquals(monthType, updated.getFieldType(1));
        assertEquals(dayType, updated.getFieldType(2));

        assertEquals(2020, updated.getValue(0));
        assertEquals(6, updated.getValue(1));
        assertEquals(15, updated.getValue(2));
    }

    @Test
    public void testWith_NewField_SameUnitDifferentRange() {
        // This tests the branch: else if (compare == 0) { if (rangeField.compareTo(loopRangeField) > 0) break; }
        // We need two field types that have the same unit but different ranges.
        // Since we can't easily manufacture custom DateTimeFieldTypes without complex mocking,
        // we rely on the standard ones provided by Joda.

        DateTimeFieldType type1 = DateTimeFieldType.yearOfStandard();
        // In Joda, most standard types have unique units. 
        // However, we can test the path by adding a field that results in index != -1 
        // or the logic flows through the loop.

        Partial partial = new Partial(ISOChronology.getInstance());
        Partial updated = partial.with(type1, 2022);

        assertEquals(1, updated.size());
        assertEquals(2022, updated.getValue(0));
    }

    @Test
    public void testWith_ChronologyConsistency() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOfStandard();
        Partial partial = new Partial(ISOChronology.getInstance());

        Partial updated = partial.with(yearType, 2022);

        assertEquals(ISOChronology.getInstance(), updated.getChronology());
    }
}
